class Solution {
  public long maxSumTrionic(int[] nums) {
    long NEG = Long.MIN_VALUE / 4;
    long s1 = NEG, s2 = NEG, s3 = NEG, best = NEG;
    for (int i = 1; i < nums.length; i++) {
      long n1 = NEG, n2 = NEG, n3 = NEG;
      if (nums[i - 1] < nums[i]) {
        n1 = nums[i] + Math.max((long) nums[i - 1], s1);
        long prev = Math.max(s2, s3);
        if (prev > NEG) n3 = nums[i] + prev;
      } else if (nums[i - 1] > nums[i]) {
        long prev = Math.max(s1, s2);
        if (prev > NEG) n2 = nums[i] + prev;
      }
      s1 = n1;
      s2 = n2;
      s3 = n3;
      best = Math.max(best, s3);
    }
    return best;
  }
}
